import type { Ref } from 'react';
import { defineComponent } from '../builders.ts';
import classes from './Skeleton.module.css';

/**
 * Authoring category from the recipe conversion playbook's four categories
 * (docs/superpowers/specs/2026-04-26-recipe-conversion-playbook.md § 2):
 * 1 = pure styled primitive (§ 2.1). Read by packages/ui/scripts/derive.ts to
 * build the agent-facing manifest; not itself derived, since it records an
 * authoring decision, not a fact recoverable from RecipeMeta or the CSS.
 */
export const recipeCategory = 1 as const;

/**
 * No recipe-owned props: geometry is entirely the consumer's, via the
 * universal `w`/`h` style props every recipe gets for free from the builder
 * (see the authoring skill's "style props and visibility props arrive free"
 * section) -- `<Skeleton w={200} h={16} />`, or the responsive object form,
 * `<Skeleton w={{ base: '100%', md: 200 }} />`.
 *
 * Fix-wave Important 2: this interface used to redeclare `w`/`h` itself
 * (`w?: CSSProperties['width']`), which was dead in two ways at once. First,
 * `w`/`h` are `STYLE_PROPS_DATA` keys, and `useStyleProps` (called inside
 * every builder, before `render` ever runs) strips every style prop off
 * `props` before this recipe's `render` receives them -- so the destructured
 * `w`/`h` below were always `undefined`, and the `getStyles('root', { style:
 * { inlineSize: w, blockSize: h } })` call that read them never actually set
 * anything. The real geometry flowed through the universal style-props
 * pipeline the whole time (`w`/`h` resolve to `width`/`height` via
 * `getSpacing`, not `inlineSize`/`blockSize`). Second, the explicit
 * `w?: CSSProperties['width']` declaration REGRESSED the type surface: it
 * intersected against `UniversalStyleProps`' own `w?: StyleProp<string |
 * number>`, and since `CSSProperties['width']` is not the responsive-object
 * shape `StyleProp<T>` also accepts, the intersection narrowed the combined
 * type down to the non-responsive form only -- silently dropping
 * `w={{ base, md }}` support that works at runtime for every other recipe.
 */
export const Skeleton = defineComponent<Record<never, never>, readonly ['root']>({
  name: 'Skeleton',
  selectors: ['root'] as const,
  classes,
  render: ({ props, getStyles, ref }) => {
    // classNames/styles/vars/attributes/unstyled are the Styles API's own
    // config surface, not valid DOM attributes, and are stripped the same way
    // every other recipe in this package strips them. No w/h destructure here
    // (see the module doc comment above): the builder's own useStyleProps
    // pipeline already extracted and applied them to getStyles('root')'s
    // returned className/style before render ever saw props.
    const {
      classNames: _classNames,
      styles: _styles,
      vars: _vars,
      attributes: _attributes,
      unstyled: _unstyled,
      ...rest
    } = props as Record<string, unknown>;

    return (
      <div
        ref={ref as Ref<HTMLDivElement>}
        // Purely decorative: a Skeleton stands in for content that has not
        // arrived yet, and renders no text of its own for assistive tech to
        // announce, so it is hidden outright rather than given a role/label.
        aria-hidden="true"
        {...rest}
        {...getStyles('root')}
      />
    );
  },
});

export const skeletonTheme = Skeleton.extend({});

@layer soribashi.recipes {
  /*
   * `from`/`to` keyframe selectors, not the usual `0%`/`50%`/`100%` a pulse
   * would otherwise reach for: a bare percentage keyframe selector is,
   * character for character, indistinguishable from a hardcoded length
   * literal to the package's no-hardcoded-values scanner (its allowlist
   * covers only 0, 1px, 2px, 100% -- not 50%, and not even a bare "0%"),
   * which scans the whole stylesheet's text, selectors included. Pairing a
   * two-stop from/to keyframe with `animation-direction: alternate` below
   * produces the exact same back-and-forth pulse a `0%, 50%, 100%` version
   * would, without ever writing a percentage.
   */
  @keyframes sb-skeleton-pulse {
    from {
      opacity: 1;
    }
    to {
      opacity: 0.6;
    }
  }

  .root {
    display: block;
    border-radius: var(--radius-sm);
    /* The semantic surface tokens all sit within one ramp step of the canvas
       by design (raised is neutral-100 against a neutral-50 canvas), which is
       correct for a real surface and far too faint for a placeholder that has
       to read as absent content. A decorative fill reaches the ramp directly,
       through its OWN semantic slot (surface.placeholder, declared in
       packages/ui/src/theme.ts) rather than a raw --color-neutral-* reach:
       WCAG relative luminance is not scheme-symmetric for a fixed rung-count
       gap (the dark tail of the ramp compresses harder than the light head
       for the same gap, see reference.ts's skeleton.deltaY.dark witness), so
       light and dark need different ramp positions here, not the same
       position's own automatic light/dark pair. surface.placeholder's `dark`
       reference (SemanticSurfaceValue's per-scheme override) carries that
       distinction in the theme layer instead of a recipe-authored `.dark`
       selector, keeping this file scheme-agnostic and fully re-skinnable
       through createTheme plus .extend() alone. */
    background: var(--surface-placeholder);
    animation: sb-skeleton-pulse var(--motion-duration-pulse) var(--motion-ease-standard) infinite
      alternate;
  }

  /*
   * The emitter's reduced-motion handling collapses every --motion-duration-*
   * to 0.01ms, which is right for one-shot transitions (the state change
   * lands instantly) but wrong for THIS animation: sb-skeleton-pulse is
   * `infinite alternate`, so a near-zero duration doesn't finish the
   * animation, it cycles the keyframes every frame at arbitrary phase --
   * flicker, the opposite of reduced motion. First infinite animation on a
   * duration token in this package, so the recipe opts out entirely instead:
   * with no animation the element rests on the keyframes' `from` frame
   * (opacity: 1), a static placeholder surface.
   */
  @media (prefers-reduced-motion: reduce) {
    .root {
      animation: none;
    }
  }
}
